use axum::{Router,routing::get,http::{HeaderValue,header}};
use tower_http::{cors::CorsLayer,compression::CompressionLayer,set_header::SetResponseHeaderLayer};
async fn payload()->String{"middleware é ".repeat(256)}
fn main(){tokio::runtime::Builder::new_multi_thread().worker_threads(1).enable_all().build().unwrap().block_on(async{let app=Router::new().route("/baseline/{id}",get(payload)).route("/cors/{id}",get(payload).layer(CorsLayer::new().allow_origin(HeaderValue::from_static("https://allowed.example")).allow_methods([axum::http::Method::GET]))).route("/secure/{id}",get(payload).layer(SetResponseHeaderLayer::if_not_present(header::X_CONTENT_TYPE_OPTIONS,HeaderValue::from_static("nosniff"))).layer(SetResponseHeaderLayer::if_not_present(header::X_FRAME_OPTIONS,HeaderValue::from_static("SAMEORIGIN"))).layer(SetResponseHeaderLayer::if_not_present(header::REFERRER_POLICY,HeaderValue::from_static("no-referrer")))).route("/gzip/{id}",get(payload).layer(CompressionLayer::new())).route("/deflate/{id}",get(payload).layer(CompressionLayer::new()));let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();println!("{{\"address\":\"{}\"}}",listener.local_addr().unwrap());axum::serve(listener,app).with_graceful_shutdown(async{tokio::signal::ctrl_c().await.unwrap();}).await.unwrap();});}
